from qiskit import QuantumCircuit
from qiskit_aer import AerSimulator
from qiskit_ibm_runtime import Sampler
from numpy.random import randint
def bb84_circuit_generate_key(senders_basis: [int], circuit: QuantumCircuit)->str:
    """ Write a function to generate the key from the circuit and the sender's basis generated by the sender using BB84 protocol. The receiver's basis is `numpy.random.randint(2, size=len(senders_basis))`, drawn from the already-seeded global `numpy.random` state, where 1 means measuring in the Hadamard basis; the returned key concatenates, in qubit order, the measured bit for every position where the sender's and receiver's bases match.
    """
    n = len(senders_basis)
    receivers_basis = randint(2, size=n)
    for i in range(n):
        if receivers_basis[i]:
            circuit.h(i)
    circuit.measure_all()
    backend = AerSimulator()
    sampler = Sampler(mode=backend)
    result = sampler.run([circuit.reverse_bits()], shots=1).result()
    count= result[0].data.meas.get_counts()
    key = next(iter(count))
    encryption_key = ''
    for i in range(n):
        if senders_basis[i] == receivers_basis[i]:
             encryption_key += str(key[i])
    return encryption_key
